def free_gaps(busy, start, end):
    gaps = []
    cursor = start                      # first minute not yet known busy
    for s, e in sorted(busy):
        if s > cursor:
            gaps.append([cursor, min(s, end)])
        cursor = max(cursor, e)
        if cursor >= end:
            break
    if cursor < end:
        gaps.append([cursor, end])
    return [g for g in gaps if g[0] < g[1]]

def two_singles(nums):
    x = 0
    for v in nums:
        x ^= v                 # a ^ b: the two singles
    low = x & -x               # a bit where they differ
    a = 0
    for v in nums:
        if v & low:
            a ^= v
    b = x ^ a
    return sorted([a, b])

