from collections import deque

def shortest_at_least(nums, k):
    pre = [0]
    for x in nums:
        pre.append(pre[-1] + x)
    dq = deque()                 # indices with rising prefix sums
    best = len(nums) + 1
    for j, p in enumerate(pre):
        while dq and p - pre[dq[0]] >= k:
            best = min(best, j - dq.popleft())
        while dq and pre[dq[-1]] >= p:
            dq.pop()
        dq.append(j)
    return best if best <= len(nums) else -1

import heapq
from collections import defaultdict

def window_median(nums, w):
    lo, hi = [], []            # lo: max-heap by negation, hi: min-heap
    late = defaultdict(int)    # values waiting to be deleted lazily
    lo_n = hi_n = 0            # live sizes
    def prune(heap, sign):
        while heap and late[sign * heap[0]] > 0:
            late[sign * heap[0]] -= 1
            heapq.heappop(heap)
    def rebalance():
        nonlocal lo_n, hi_n
        if lo_n > hi_n + 1:
            heapq.heappush(hi, -heapq.heappop(lo))
            lo_n -= 1; hi_n += 1; prune(lo, -1)
        elif lo_n < hi_n:
            heapq.heappush(lo, -heapq.heappop(hi))
            hi_n -= 1; lo_n += 1; prune(hi, 1)
    def add(x):
        nonlocal lo_n, hi_n
        if not lo or x <= -lo[0]:
            heapq.heappush(lo, -x); lo_n += 1
        else:
            heapq.heappush(hi, x); hi_n += 1
        rebalance()
    def remove(x):
        nonlocal lo_n, hi_n
        late[x] += 1
        if lo and x <= -lo[0]:
            lo_n -= 1
            if x == -lo[0]: prune(lo, -1)
        else:
            hi_n -= 1
            if hi and x == hi[0]: prune(hi, 1)
        rebalance()
    out = []
    for i, x in enumerate(nums):
        add(x)
        if i >= w:
            remove(nums[i - w])
        if i >= w - 1:
            out.append(float(-lo[0]) if w % 2 else (-lo[0] + hi[0]) / 2)
    return out
